#!/usr/bin/env python3
# =====================================================================
#  apply_vet_mode_follow.py  —  fence VET_MODE_FOLLOW_20261125  (on main 7a981179, v12.0.15)
#  DEF-102 · TD-088
#
#  25 Nov, Dhivakar's Mac: VET armed at 08:30 as PAPER, Settings were set to
#  LIVE at 08:46, and the 09:20 entry was booked PAPER. VET read the mode
#  ONCE, at arm, and built its broker executor only if it was LIVE then.
#  Every other live strategy reads the mode at entry and pre-builds its
#  executor ("a PAPER→LIVE flip mid-session never needs a restart").
#
#  Now VET does the same:
#   * the mode is the one Settings say at the moment of each entry;
#   * an open position keeps the mode it opened in until it exits (the
#     25 Nov paper trade runs to its own exit; LIVE starts with the next
#     entry, a FLIP's re-entry included);
#   * at arm, a carried open position of EITHER mode is adopted in its own
#     mode (before, a switch overnight left it unmanaged — a LIVE carry
#     after a switch to PAPER was orphaned);
#   * Settings LIVE but no broker executor → no entry (never a LIVE row
#     with paper fills); an in-app alert says why.
#
#   backend/app/engine/vet/vet_manager.py        carried_book_mode(), sync_mode()
#   backend/app/engine/vet/vet_selection_loop.py executor pre-built, book from open
#        positions, Settings mode read at each decision
#   backend/app/engine/vet/test_vet_manager.py   TC-VET-0332…0343
#   backend/app/engine/test_mode_follow_fleet.py NEW  TC-FLEET-0104…0105 (every engine)
#   scripts/checklist/items.py                   CL-16 (a commit that rebuilds the
#        DEF-102 shape fails)
#   scripts/test_reliability_checklist.py        TC-GATE-0059…0061; 0038/0040 count 16
#   REPO_MAP.md, scripts/regression/MASTER_SUITE.md   regenerated
#  Build copies under desktop/src-tauri/ are written too when present.
#  Every edited file gets a .bak-VET_MODE_FOLLOW_20261125 copy.
#
#  Run ONLY this script:
#     cd ~/dev/scalp-app && python3 apply_vet_mode_follow.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: commit, ./deploy-scalp.command (release).
# =====================================================================
ITEMS = [
    {'path': 'backend/app/engine/vet/vet_manager.py', 'orig': 'c12caece2a0720b8bd27e63fe7385bd46cb7643150448fbbf28367c5eb46c46e', 'new': '90a7b8efa4d9320a28da6e447be73e7a9b74a089ccac6947cf431029aa771c6c', 'blob': ''},
    {'path': 'backend/app/engine/vet/vet_selection_loop.py', 'orig': '56fb54d36f08905004559bdf00907a8fc72c39391c85e7b4c7cf030a3c0afced', 'new': 'd3c660c84399063da338adbdbb98ad0a65076b45624927dfd663e627e747e4d0', 'blob': ''},
    {'path': 'backend/app/engine/vet/test_vet_manager.py', 'orig': '9f92f71e7cd59682ebbd6cde37bab8068a61f8495cfaf10234752c7d15bc2026', 'new': '79d9cc88694040531f641149c4097f667881e94595c06bc2963bbfc6837d377d', 'blob': ''},
    {'path': 'backend/app/engine/test_mode_follow_fleet.py', 'orig': None, 'new': '91f7e30df9c94b6dbf3914c68282b9baa7ad54ca0f3ae21b6384d8102b4ec1d7', 'blob': ''},
    {'path': 'scripts/checklist/items.py', 'orig': '6c2ff25372c5a6256e9e0f88b4e5f097dc0877a6b273ef1c246338eb437c379b', 'new': 'b52f4f5b4ab80d8fc07723cd9acc72053a73fae569adecd4ea8b3fb595180564', 'blob': ''},
    {'path': 'scripts/test_reliability_checklist.py', 'orig': '55bc81833e822f4d626ba377d23efb0db0a6eff33846ebfaede821ef0b080bee', 'new': '92d5c9b21292a094a078421de31987e161b8c928dea23cfc21320dba7a2df0fc', 'blob': ''},
]
import base64, hashlib, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "VET_MODE_FOLLOW_20261125"
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/"}
PARENTS = {"backend/app/engine/vet/vet_manager.py": ["VET_KILL_BLOCK_20261123", "BROKER_TRUTH_20261114"],
           "backend/app/engine/vet/vet_selection_loop.py": ["VET_KILL_BLOCK_20261123", "VET_NEAR_OBS_20261106"],
           "scripts/checklist/items.py": ["ISOLATED_HOME_20261122"]}
TESTS = ["backend/app/engine/vet/test_vet_manager.py", "backend/app/engine/test_mode_follow_fleet.py",
         "backend/app/engine/vet/test_vet_sltp_live.py", "backend/app/engine/vet/test_vet_e2e.py",
         "backend/app/trading/test_fleet_modes.py", "backend/app/engine/test_fleet_live.py",
         "scripts/test_reliability_checklist.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


def refresh_master():
    """MASTER_SUITE.md (every suite's hash + TC IDs) and REPO_MAP.md (suite
    counts) follow the files on disk; regenerated after a write or rollback."""
    for gen, args_, name in (("scripts/regression/master_suite.py", ["refresh"], "MASTER_SUITE.md"),
                             ("scripts/gen_repo_map.py", [], "REPO_MAP.md")):
        g = os.path.join(repo, gen)
        if not os.path.exists(g):
            continue
        r = subprocess.run([sys.executable, g] + args_, cwd=repo, capture_output=True, text=True, timeout=300)
        msg = ((r.stdout or "") + (r.stderr or "")).strip().splitlines()
        say("  " + (msg[-1] if msg else f"{name} refreshed") if r.returncode == 0
            else f"  !! {name} refresh failed — pre-commit will refresh it")


def rd(p):
    if not os.path.exists(p):
        return None
    with open(p, "rb") as f:
        return f.read()


# ── rollback ─────────────────────────────────────────────────────────
if "--rollback" in args:
    later = [os.path.relpath(p, repo) for it, p, build in targets()
             if not build and os.path.exists(p + ".bak-" + FENCE) and sha(rd(p) or b"") != it["new"]]
    if later:
        die("cannot roll back — changed again after this script: " + ", ".join(later)
            + ". Roll the later fixes back first, newest first.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p) and sha(rd(p)) == it["new"]:
            os.remove(p)                  # a file this script created
            n += 1
    refresh_master()
    say(f"rolled back {n} file(s). Then: ./desktop/build-scalp.sh backend")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = any(not b and FENCE.encode() in (rd(p) or b"") for _, p, b in targets())
for it, p, build in targets():
    cur = rd(p)
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
    elif cs == it["orig"]:                # (None == None: a NEW file not there yet)
        plan.append((it, p, cur, build))
    elif build:
        if cur is not None and it["orig"] is not None:
            skipped.append(rel)           # stale build copy — the build re-syncs it
    elif cur is None:
        die(f"{rel} is missing")
    elif _applied:
        later.append(rel)
    else:
        die(f"{rel} is not the version this script was built on (main 7a981179) — "
            "pull the latest main and ask for a rebuilt script")
if not plan:
    say(f"✓ already applied ({done} file(s) in place"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are not "
        "patched — check git status first")
for rel, fences in PARENTS.items():
    miss = [f for f in fences if f.encode() not in (rd(os.path.join(repo, rel)) or b"")]
    if miss:
        die(f"{rel} lacks {', '.join(miss)} — pull the latest main first")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b] + ["scripts/regression/MASTER_SUITE.md", "REPO_MAP.md"]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [ln for ln in st.splitlines() if ln[:2].strip() and not ln.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty)
                + "\n  (commit/stash them, or --allow-dirty)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="vet_mode_follow_")
blobs = {}
try:
    for it in ITEMS:
        b = zlib.decompress(base64.b64decode(it["blob"]))
        if sha(b) != it["new"]:
            die(f"payload for {it['path']} is corrupt")
        blobs[it["path"]] = b
        f = os.path.join(tmp, os.path.basename(it["path"]))
        with open(f, "wb") as h:
            h.write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
finally:
    shutil.rmtree(tmp, ignore_errors=True)
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
                continue
            with open(p, "wb") as h:
                h.write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        bak = p + ".bak-" + FENCE
        if cur is not None and not os.path.exists(bak):
            shutil.copy2(p, bak)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        t = p + ".tmp-" + FENCE
        with open(t, "wb") as h:
            h.write(blobs[it["path"]])
        if cur is not None:
            shutil.copymode(p, t)
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")
refresh_master()

# ── 5. tests (scripts/run_suites.py: right runner per suite, throw-away HOME) ──
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    def _pytest_direct(rel):
        """run_suites runs pytest files with backend/venv's Python; when that
        venv has no pytest, run the file with this Python instead, in a
        throw-away HOME (never the live ~/.scalp-app)."""
        import importlib.util
        if importlib.util.find_spec("pytest") is None:
            return None, "pytest is not installed for " + sys.executable
        home = tempfile.mkdtemp(prefix="vmf_home_")
        try:
            env = {k: v for k, v in os.environ.items()
                   if k not in ("SCALP_APP_HOME", "DB_PATH", "SCALP_DATA_DIR", "SCALP_LOG_DIR", "SCALP_STATE_DIR")}
            env.update(HOME=home, USERPROFILE=home, SCALP_TEST_MODE="1",
                       PYTHONPATH=os.pathsep.join([os.path.join(repo, "backend"), "."]))
            full = os.path.join(repo, rel)
            rr = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider",
                                 os.path.basename(full)], cwd=os.path.dirname(full), env=env,
                                capture_output=True, text=True, timeout=900)
            return rr.returncode, ((rr.stdout or "") + (rr.stderr or "")).strip()
        finally:
            shutil.rmtree(home, ignore_errors=True)

    failed, envmiss = [], []
    for t in TESTS:
        r = subprocess.run([sys.executable, os.path.join(repo, "scripts", "run_suites.py"), t],
                           cwd=repo, capture_output=True, text=True, timeout=1800)
        out = ((r.stdout or "") + (r.stderr or "")).strip()
        if r.returncode != 0 and "No module named pytest" in out:
            rc, out2 = _pytest_direct(t)
            last = (out2.splitlines() or [""])[-1]
            if rc is None:
                envmiss.append(t)
                say(f"  ? {t}: not runnable here ({out2})")
            elif rc == 0:
                say(f"  ✓ {t}  {last}  (run with {sys.executable}; the backend venv has no pytest)")
            else:
                failed.append(t)
                say(f"  ✗ {t}\n" + "\n".join("      " + ln for ln in out2.splitlines()[-25:]))
            continue
        last = (out.splitlines() or [""])[-1]
        if r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + ln for ln in out.splitlines()[-25:]))
    if failed:
        restore()
        refresh_master()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: " + ", ".join(envmiss) + " could not run here (no pytest) — run them where pytest is installed")

say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: commit, then ./deploy-scalp.command.")
say("  Undo: python3 apply_vet_mode_follow.py --rollback")
